+void CoalescedEncodingAnalysis::computeSliceInfo(FunctionOpInterface func) {
+  SmallVector<SliceNode> nodes;
+  DenseMap<Operation *, unsigned> nodeIndices;
+  func.walk([&](Operation *op) {
+    nodeIndices[op] = nodes.size();
+    nodes.push_back({op, {}});
